cd /work; php -m | grep -i -E 'pdo|pgsql|intl|curl|json'; php -r '
$p=new PDO("pgsql:host=postgres;port=5432;dbname=llmapi_eval","eval_rw","eval_rw");
foreach(["author","book","customer","purchase","purchase_line"] as $t){
 echo "== $t\n";
 foreach($p->query("select column_name,data_type,is_nullable,column_default from information_schema.columns where table_schema=current_schema() and table_name='$t' order by ordinal_position") as $r) echo implode(" | ",$r),"\n";
}
foreach($p->query("select table_name, constraint_type, pg_get_constraintdef(c.oid) d from information_schema.table_constraints t join pg_constraint c on c.conname=t.constraint_name where t.table_schema=current_schema()") as $r) echo implode(" | ",$r),"\n";
echo "counts:\n";
foreach(["author","book","customer","purchase","purchase_line"] as $t){ echo $t," ",$p->query("select count(*) from $t")->fetchColumn(),"\n"; }
echo current_schema(),"\n";
'

mkdir -p /tmp/scratch && cat > /tmp/scratch/schema.php <<'EOF'
<?php
$p=new PDO("pgsql:host=postgres;port=5432;dbname=llmapi_eval","eval_rw","eval_rw");
$p->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
foreach(["author","book","customer","purchase","purchase_line"] as $t){
 echo "== $t\n";
 $st=$p->prepare("select column_name,data_type,is_nullable,column_default from information_schema.columns where table_schema=current_schema() and table_name=? order by ordinal_position");
 $st->execute([$t]);
 foreach($st->fetchAll(PDO::FETCH_NUM) as $r) echo implode(" | ",$r),"\n";
}
echo "constraints:\n";
foreach($p->query("select conrelid::regclass, conname, pg_get_constraintdef(oid) from pg_constraint where connamespace=current_schema()::regnamespace") as $r) echo implode(" | ",$r),"\n";
echo "counts:\n";
foreach(["author","book","customer","purchase","purchase_line"] as $t){ echo $t," ",$p->query("select count(*) from $t")->fetchColumn(),"\n"; }
echo current_schema(),"\n";
EOF
php -I /tmp/scratch/schema.php 2>&1 || php /tmp/scratch/schema.php

cd /work; grep -A2 '"name": "doctrine/dbal"' composer.lock | head -3; grep -A2 '"name": "api-platform/core"' composer.lock | head -3; cat > /tmp/scratch/data.php <<'EOF'
